('alict_00353', 12, 'General ICT', 'Who invented the logarithmic theories that used to easily multiply and divide numbers by doing addition and subtraction in 1617?', '["John Napier", "William Oughtred", "Blaise Pascal", "Gottfried Wilhelm Leibniz", "Joseph Jacquard"]'::jsonb, 1, 'John Napier In 1617 John Napier introduced logarithmic theory. Logarithms can easily add and subtract multiply and divide. Logarithmic tables should be used for that. Later he introduced an alternative method by recording the logarithms of ivory strips. These are called Napier''s bones', NULL, NULL, 'medium', 'General ICT', 2027, 353, '2027 Quiz Series'),
('alict_00354', 12, 'General ICT', 'x + 101010102 = 1416 × 248 Which of the following matches the value of x?', '["400", "200", "130", "100", "230"]'::jsonb, 5, 'x + 101010102 = 1416 × 248 In order to solve this first let''s convert every term into decimal', NULL, NULL, 'medium', 'General ICT', 2027, 354, '2027 Quiz Series'),
('alict_00355', 12, 'General ICT', 'Which of the following pioneers in computer science is most closely associated with the stored which is fundamental to modern computing architectures?', '["John V on Neumann", "Ada Lovelace", "John Eckert", "Charles Babbage", "Blaise Pascal"]'::jsonb, 1, 'John von Neumann Introduced the stored -program where both data and programs are stored in a computer''s forming the basis of most modern computer architectures. fndfyda', NULL, NULL, 'medium', 'General ICT', 2027, 355, '2027 Quiz Series'),
('alict_00356', 12, 'General ICT', 'Consider the following 3458 = 3458 = 22910 = E516 Which of the following is correct?', '["Only A is correct", "Only A and B are correct", "Only B and C are correct", "All statements are correct", "None of the statements are correct"]'::jsonb, 4, 'Correct answer: "All statements are correct".', NULL, NULL, 'medium', 'General ICT', 2027, 356, '2027 Quiz Series'),
('alict_00357', 12, 'General ICT', 'What is the unit of speed used for Super Computer?', '["Gigahertz", "Megahertz", "FLOPS", "GLOPS", "Terahertz"]'::jsonb, 3, 'Supercomputers are measured in terms of their ability to perform floating -point calculations per second. The unit FLOPS (Floating Point Operations Per Second) is the standard metric used to evaluate a supercomputer''s performance', NULL, NULL, 'medium', 'General ICT', 2027, 357, '2027 Quiz Series'),
