('alict_00361', 12, 'General ICT', 'Consider the following 110112 = 2710 = 1B16 = 338 Which of the following is correct?', '["Only A is correct", "Only A and B are correct", "Only B and C are correct", "All statements are correct", "None of the statements are correct"]'::jsonb, 4, 'Correct answer: "All statements are correct".', NULL, NULL, 'medium', 'General ICT', 2027, 361, '2027 Quiz Series'),
('alict_00362', 12, 'General ICT', 'Which of the following imaging techniques is most suitable for detecting metabolic activity in tissues and is commonly used in oncology for cancer staging?', '["Computed Tomography (CT)", "Magnetic Resonance Imaging (MRI)", "Positron Emission Tomography (PET)", "Electrocardiography (ECG)", "Electroencephalography (EEG)"]'::jsonb, 3, 'Computed Tomography (CT) CT scans provide detailed anatomical images using X -rays but do not measure metabolic activity. They are excellent for visualizing structures like and tumors but cannot differentiate between active and inactive tissues based on metabolism. CT u', NULL, NULL, 'medium', 'General ICT', 2027, 362, '2027 Quiz Series'),
