('alict_00469', 12, 'General ICT', 'Given the following page which physical address does the virtual address 001010100100 map to?', '["001110100100", "000011010100", "001111010100", "001001010100", "110010010100"]'::jsonb, 1, 'Correct answer: "001110100100".', NULL, NULL, 'medium', 'General ICT', 2027, 469, '2027 Quiz Series'),
('alict_00470', 12, 'General ICT', 'Which of the following is not an advantage of using ICT in agriculture?', '["Improving productivity", "Remote monitoring capability", "Dependence on technology", "Being able to access the online marketplace", "Reduced manual labor requirements"]'::jsonb, 3, 'Option 1: ICT can help improve productivity by providing better access to optimizing resource and automating processes', NULL, NULL, 'medium', 'General ICT', 2027, 470, '2027 Quiz Series'),
('alict_00471', 12, 'General ICT', 'Which event is considered by many to mark the beginning of the personal computer revolution?', '["The release of the Apple Lisa. Apple Lisa", "The introduction of the IBM PC. IBM y\u00f7kajd", "The development of the ARPANET (precursor to the internet). ARPANET", "The invention of the microprocessor. ilikh fidhd", "The creation of the first graphical user interface (GUI)"]'::jsonb, 2, 'The introduction of the IBM PC in 1981 is widely considered the beginning of the personal computer revolution. It brought computing power to individuals and small setting the stage for widespread adoption of personal computers. 1981 mqoa', NULL, NULL, 'medium', 'General ICT', 2027, 471, '2027 Quiz Series'),
('alict_00472', 12, 'General ICT', 'Select incorrect statement about flipflops', '["flip-flops are examples for the usage of logic gates", "S-R lip-flops are nothing but a single bit memory storage. S-R", "Flip lops are having two inputs and two one of its outputs is the complement of the other", "Only two types of flip flops are available and their output always depend on current inputs Flip", "Flip flops are examples for sequential circuits and used to create a memory"]'::jsonb, 4, 'Correct answer: "Only two types of flip flops are available and their output always depend on current inputs Flip".', NULL, NULL, 'medium', 'General ICT', 2027, 472, '2027 Quiz Series'),
